import { sql, type SQL } from "drizzle-orm";
import * as pg from "drizzle-orm/pg-core";

export const opportunitySql = pg.pgTable("opportunity", {
  id: pg.integer().primaryKey().generatedAlwaysAsIdentity(),
  cmcId: pg.integer().notNull(),
  exchangeBuyId: pg.integer().notNull(),
  exchangeSellId: pg.integer().notNull(),
  buyPrice: pg.doublePrecision().notNull(),
  sellPrice: pg.doublePrecision().notNull(),
  buyVolume: pg.doublePrecision().notNull(),
  sellVolume: pg.doublePrecision().notNull(),
  // generated by calculateProfitPercentage we need percentage
  profitPercentage: pg
    .doublePrecision()
    .generatedAlwaysAs((): SQL => sql`(sell_price - buy_price) / buy_price`),
  // volume based on Math.min(buyVolume, sellVolume) * (sell_price - buy_price) / buy_price
  profitVolume: pg
    .doublePrecision()
    .generatedAlwaysAs(
      (): SQL => sql`min(buy_volume, sell_volume) * profit_percentage`,
    ),
});
